import * as fs from 'fs';

/**
 * Deeply compares two values for equality.
 */
function isEqual(obj1: any, obj2: any): boolean {
  if (obj1 === obj2) return true;

  if (
    typeof obj1 !== 'object' ||
    obj1 === null ||
    typeof obj2 !== 'object' ||
    obj2 === null
  ) {
    return false;
  }

  const keys1 = Object.keys(obj1);
  const keys2 = Object.keys(obj2);

  if (keys1.length !== keys2.length) return false;

  for (const key of keys1) {
    if (!Object.prototype.hasOwnProperty.call(obj2, key) || !isEqual(obj1[key], obj2[key])) {
      return false;
    }
  }

  return true;
}

/**
 * Deeply merges two JSON values based on the specified rules.
 */
function deepMerge(a: any, b: any): any {
  const isObject = (val: any) => val !== null && typeof val === 'object' && !Array.isArray(val);
  const isArray = (val: any) => Array.isArray(val);

  // Rule: If both values are arrays: concatenate and remove duplicates (preserve order)
  if (isArray(a) && isArray(b)) {
    const combined = [...a];
    for (const item of b) {
      if (!combined.some((existing) => isEqual(existing, item))) {
        combined.push(item);
      }
    }
    return combined;
  }

  // Rule: If both values are objects: merge recursively
  if (isObject(a) && isObject(b)) {
    const result = { ...a };
    for (const key in b) {
      if (Object.prototype.hasOwnProperty.call(b, key)) {
        if (Object.prototype.hasOwnProperty.call(result, key)) {
          result[key] = deepMerge(result[key], b[key]);
        } else {
          result[key] = b[key];
        }
      }
    }
    return result;
  }

  // Rule: If scalar conflict (or type mismatch): value from B overrides A
  // Rule: Keys only in A or only in B are included as-is (handled by the object merge loop)
  return b;
}

/**
 * Recursively sorts all object keys alphabetically at every level.
 */
function sortKeys(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(sortKeys);
  } else if (obj !== null && typeof obj === 'object') {
    const sorted: any = {};
    const keys = Object.keys(obj).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(obj[key]);
    }
    return sorted;
  }
  return obj;
}

