import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrorCounts = new HashMap<>();
        TreeSet<String> uniqueErrorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                int timestampEnd = line.indexOf("] ");
                if (timestampEnd == -1) continue;

                String timestamp = line.substring(1, timestampEnd);
                String remainder = line.substring(timestampEnd + 2);

                int levelEnd = remainder.indexOf(" (");
                if (levelEnd == -1) continue;
                String level = remainder.substring(0, levelEnd);

                int componentStart = remainder.indexOf("(");
                int componentEnd = remainder.indexOf(")");
                if (componentStart == -1 || componentEnd == -1) continue;
                String component = remainder.substring(componentStart + 1, componentEnd);

                int messageStart = remainder.indexOf(" - ");
                if (messageStart == -1) continue;
                String message = remainder.substring(messageStart + 3);

                // Extract hour (HH) from "YYYY-MM-DD HH:MM:SS"
                String hour = timestamp.substring(11, 13);
                String hourKey = hour + ":00";

                // Update counts
                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                hourCounts.put(hourKey, hourCounts.getOrDefault(hourKey, 0) + 1);

                if ("ERROR".equals(level)) {
                    componentErrorCounts.put(component, componentErrorCounts.getOrDefault(component, 0) + 1);
                    uniqueErrorMessages.add(message);
                }
            }

            // Output formatting
            System.out.println("=== Log Analysis ===");
            System.out.println();

            System.out.println("Entries by Level:");
            for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
                System.out.println("  " + entry.getKey() + ": " + entry.getValue());
            }
            System.out.println();

            String maxComp = "";
            int maxErrors = -1;
            for (Map.Entry<String, Integer> entry : componentErrorCounts.entrySet()) {
                if (entry.getValue() > maxErrors) {
                    maxErrors = entry.getValue();
                    maxComp = entry.getKey();
                } else if (entry.getValue() == maxErrors) {
                    if (maxComp.isEmpty() || entry.getKey().compareTo(maxComp) < 0) {
                        maxComp = entry.getKey();
                    }
                }
            }
            if (!maxComp.isEmpty()) {
                System.out.println("Component with Most Errors: " + maxComp + " (" + maxErrors + " errors)");
            } else {
                System.out.println("Component with Most Errors: None (0 errors)");
            }
            System.out.println();

            System.out.println("Unique Error Messages:");
            for (String msg : uniqueErrorMessages) {
                System.out.println("  - " + msg);
            }
            System.out.println();

            String busiestHour = "";
            int maxHourCount = -1;
            for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
                if (entry.getValue() > maxHourCount) {
                    maxHourCount = entry.getValue();
                    busiestHour = entry.getKey();
                } else if (entry.getValue() == maxHourCount) {
                    if (busiestHour.isEmpty() || entry.getKey().compareTo(busiestHour) < 0) {
                        busiestHour = entry.getKey();
                    }
                }
            }
            if (!busiestHour.isEmpty()) {
                System.out.println("Busiest Hour: " + busiestHour + " (" + maxHourCount + " entries)");
            }

        } catch (IOException e) {
            // Handle or ignore file access issues
        }
    }
