import Foundation

let path = "/tmp/…/app.log"

do {
    let content = try String(contentsOfFile: path, encoding: .utf8)
    let lines = content.components(separatedBy: .newlines)

    var levelCounts: [String: Int] = [:]
    var errorCountsByComponent: [String: Int] = [:]
    var uniqueErrorMessages = Set<String>()
    var hourCounts: [String: Int] = [:]

    for line in lines {
        if line.trimmingCharacters(in: .whitespaces).isEmpty { continue }

        guard let firstBracket = line.firstIndex(of: "["),
              let firstCloseBracket = line.firstIndex(of: "]"),
              let firstParen = line.firstIndex(of: "("),
              let secondParen = line.firstIndex(of: ")") else {
            continue
        }

        let timestamp = String(line[line.index(after: firstBracket)..<firstCloseBracket])
        let level = String(line[line.index(after: firstCloseBracket)..<firstParen]).trimmingCharacters(in: .whitespaces)
        let component = String(line[line.index(after: firstParen)..<secondParen])

        let messagePart = line[line.index(after: secondParen)..<line.endIndex]
        let messageParts = messagePart.split(separator: " - ", maxSplits: 1, omittingEmptySubsequences: false)
        let message = messageParts.count > 1 ? String(messageParts[1]) : String(messageParts[0])

        levelCounts[level, default: 0] += 1

        let timeParts = timestamp.components(separatedBy: " ")
        if timeParts.count >= 2 {
            let timeStr = timeParts[1]
            let hourStr = timeStr.split(separator: ":")[0].trimmingCharacters(in: .whitespaces)
            let formattedHour = hourStr.count == 1 ? "0\(hourStr)" : hourStr
            hourCounts[formattedHour + ":00", default: 0] += 1
        }

        if level == "ERROR" {
            errorCountsByComponent[component, default: 0] += 1
            uniqueErrorMessages.insert(message)
        }
    }

    print("=== Log Analysis ===")
    print("")

    print("Entries by Level:")
    for level in levelCounts.keys.sorted() {
        print("  \(level): \(levelCounts[level]!)")
    }
    print("")

    let maxErrorComp = errorCountsByComponent.max(by: { $0.value < $1.value })
    if let comp = maxErrorComp {
        print("Component with Most Errors: \(comp.key) (\(comp.value) errors)")
    } else {
        print("Component with Most Errors: None (0 errors)")
    }
    print("")

    print("Unique Error Messages:")
    for msg in uniqueErrorMessages.sorted() {
        print("  - \(msg)")
    }
    print("")

    let maxHour = hourCounts.max(by: { $0.value < $1.value })
    if let hour = maxHour {
        print("Busiest Hour: \(hour.key) (\(hour.value) entries)")
    } else {
        print("Busiest Hour: N/A (0 entries)")
    }

} catch {
    // Silent exit on file access error
}

import * as fs from 'fs';

const filePath = '/tmp/…/employees.csv';

/**
 * Formats a number as a currency string with specified decimal places.
 * Uses the 'en-US' locale to ensure comma separators.
 */
function formatCurrency(num: number, decimals: number = 0): string {
    const formatted = num.toLocaleString('en-US', {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
    });
    return `$${formatted}`;
}

/**
 * Parses a single CSV line, handling basic quoted values.
 */
function parseCSVLine(line: string): string[] {
    const result: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
        const char = line[i];
        if (char === '"') {
            inQuotes = !inQuotes;
        } else if (char === ',' && !inQuotes) {
            result.push(current.trim().replace(/^"|"$/g, ''));
            current = '';
        } else {
            current += char;
        }
    }
    result.push(current.trim().replace(/^"|"$/g, ''));
    return result;
}

function main() {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.trim().split(/\r?\n/);
        if (lines.length < 2) return;

        const data = lines.slice(1).map(line => {
            const cols = parseCSVLine(line);
            return {
                id: cols[0],
                name: cols[1],
                department: cols[2],
                salary: parseFloat(cols[3]) || 0,
                startDate: cols[4],
                rating: cols[5]
            };
        });

        // 1. Average Salary by Department
        const deptSalaries: Record<string, number[]> = {};
        data.forEach(emp => {
            if (!deptSalaries[emp.department]) deptSalaries[emp.department] = [];
            deptSalaries[emp.department].push(emp.salary);
        });

        const sortedDepts = Object.keys(deptSalaries).sort();

        // 2. Highest Paid
        let highestPaid = data[0];
        data.forEach(emp => {
            if (emp.salary > highestPaid.salary) {
                highestPaid = emp;
            }
        });

