use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::BTreeMap;

fn format_int(val: i64) -> String {
    let s = val.to_string();
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_float(val: f64) -> String {
    let s = format!("{:.2}", val);
    let parts: Vec<&str> = s.split('.').collect();
    let integer_part = parts[0];
    let decimal_part = parts[1];

    let mut result = String::new();
    let chars: Vec<char> = integer_part.chars().collect();
    let len = chars.len();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result.push('.');
    result.push_str(decimal_part);
    result
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let file = File::open(path).expect("Could not open file");
    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    // Skip header
    let _header = lines.next();

    let mut dept_salaries: BTreeMap<String, (f64, usize)> = BTreeMap::new();
    let mut dept_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut total_budget = 0.0;
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary = -1.0;

    for line in lines {
        let l = line.expect("Failed to read line");
        let parts: Vec<&str> = l.split(',').collect();
        if parts.len() >= 4 {
            let name = parts[1].trim().to_string();
            let dept = parts[2].trim().to_string();
            let salary = parts[3].trim().parse::<f64>().unwrap_or(0.0);

            total_budget += salary;

            let entry = dept_salaries.entry(dept.clone()).or_insert((0.0, 0));
            entry.0 += salary;
            entry.1 += 1;

            let count = dept_counts.entry(dept).or_insert(0);
            *count += 1;

            if salary > highest_paid_salary {
                highest_paid_salary = salary;
                highest_paid_name = name;
            }
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, (sum, count)) in &dept_salaries {
        let avg = sum / (*count as f64);
        println!("  {}: ${}", dept, format_float(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_paid_name, format_int(highest_paid_salary as i64));
    println!();
    println!("Departments with >2 employees:");
    for (dept, &count) in &dept_counts {
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_int(total_budget as i64));
