import java.io.*;
import java.util.*;
import java.text.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/employees.csv";
        List<Employee> employees = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line = br.readLine(); // Skip header
            while ((line = br.readLine()) != null) {
                String[] parts = line.split(",");
                if (parts.length >= 4) {
                    Employee e = new Employee();
                    e.name = parts[1].trim();
                    e.department = parts[2].trim();
                    String salaryStr = parts[3].trim().replaceAll("[^0-9]", "");
                    if (!salaryStr.isEmpty()) {
                        e.salary = Integer.parseInt(salaryStr);
                        employees.add(e);
                    }
                }
            }
        } catch (Exception e) {
            // Handle file not found or parsing errors gracefully
        }

        Map<String, List<Integer>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCounts = new HashMap<>();
        int maxSalary = -1;
        String highestPaidName = "";
        long totalBudget = 0;

        for (Employee e : employees) {
            deptSalaries.computeIfAbsent(e.department, k -> new ArrayList<>()).add(e.salary);
            deptCounts.put(e.department, deptCounts.getOrDefault(e.department, 0) + 1);
            totalBudget += e.salary;
            if (e.salary > maxSalary) {
                maxSalary = e.salary;
                highestPaidName = e.name;
            }
        }

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");

        NumberFormat avgFormat = NumberFormat.getCurrencyInstance(Locale.US);
        avgFormat.setMinimumFractionDigits(2);
        avgFormat.setMaximumFractionDigits(2);

        for (Map.Entry<String, List<Integer>> entry : deptSalaries.entrySet()) {
            String dept = entry.getKey();
            List<Integer> salaries = entry.getValue();
            double sum = 0;
            for (int s : salaries) sum += s;
            double avg = sum / salaries.size();
            System.out.println("  " + dept + ": " + avgFormat.format(avg));
        }

        System.out.println();

        NumberFormat intFormat = NumberFormat.getCurrencyInstance(Locale.US);
        intFormat.setMinimumFractionDigits(0);
        intFormat.setMaximumFractionDigits(0);

        System.out.println("Highest Paid: " + highestPaidName + " (" + intFormat.format(maxSalary) + ")");
        System.out.println();
        System.out.println("Departments with >2 employees:");

        List<String> sortedDepts = new ArrayList<>(deptCounts.keySet());
        Collections.sort(sortedDepts);
        for (String dept : sortedDepts) {
            if (deptCounts.get(dept) > 2) {
                System.out.println("  " + dept + " (" + deptCounts.get(dept) + " employees)");
            }
        }

        System.out.println();
        System.out.println("Total Budget: " + intFormat.format(totalBudget));
    }

    static class Employee {
        String name;
        String department;
        int salary;
    }
}

import json

def deep_merge(a, b):
    """
    Deeply merges two JSON-compatible objects based on the following rules:
    - If both values are objects (dicts): merge recursively.
    - If both values are arrays (lists): concatenate and remove duplicates (preserve order).
    - If scalar conflict: value from B overrides A.
    - Keys only in A or only in B are included as-is.
    """
    if isinstance(a, dict) and isinstance(b, dict):
        merged = a.copy()
        for key, value in b.items():
            if key in merged:
                merged[key] = deep_merge(merged[key], value)
            else:
                merged[key] = value
        return merged
    elif isinstance(a, list) and isinstance(b, list):
        res = []
        # Add items from A first, preserving order and removing internal duplicates
        for item in a:
            if item not in res:
                res.append(item)
        # Add new items from B, preserving order and removing duplicates
        for item in b:
            if item not in res:
                res.append(item)
        return res
    else:
        # Scalar conflict or type mismatch: B overrides A
        return b

