const fs = require('fs');

const filePath = '/tmp/…/app.log';

function main() {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split(/\r?\n/);

        const levels = new Map<string, number>();
        const componentErrors = new Map<string, number>();
        const errorMessages = new Set<string>();
        const hourCounts = new Map<string, number>();

        // Regex to capture:
        // 1. Full timestamp
        // 2. Hour (1 or 2 digits)
        // 3. Level
        // 4. Component
        // 5. Message
        const regex = /^\[(\d{4}-\d{2}-\d{2} (\d{1,2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

        for (const line of lines) {
            const match = line.match(regex);
            if (match) {
                const [_, timestamp, hour, level, component, message] = match;

                // Level counts
                levels.set(level, (levels.get(level) || 0) + 1);

                // Hour counts (ensuring 2-digit hour)
                const formattedHour = hour.padStart(2, '0');
                const hourKey = `${formattedHour}:00`;
                hourCounts.set(hourKey, (hourCounts.get(hourKey) || 0) + 1);

                // Error specific counts and unique messages
                if (level === 'ERROR') {
                    componentErrors.set(component, (componentErrors.get(component) || 0) + 1);
