char *my_strdup(const char *s) {
    char *d = malloc(strlen(s) + 1);
    if (d) strcpy(d, s);
    return d;
}

char *trim(char *str) {
    while (*str == ' ' || *str == '\t' || *str == '\n' || *str == '\r') str++;
    if (*str == 0) return str;
    char *end = str + strlen(str) - 1;
    while (end > str && (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) end--;
    *(end + 1) = '\0';
    return str;
}

void print_money_int(double amount) {
    long long integral = (long long)amount;
    char int_str[64];
    sprintf(int_str, "%lld", integral);
    int len = strlen(int_str);
    printf("$");
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            printf(",");
        }
        printf("%c", int_str[i]);
    }
}

void print_money_double(double amount) {
    long long integral = (long long)amount;
    int fractional = (int)((amount - (double)integral) * 100 + 0.5);
    if (fractional == 100) {
        integral++;
        fractional = 0;
    }
    char int_str[64];
    sprintf(int_str, "%lld", integral);
    int len = strlen(int_str);
    printf("$");
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            printf(",");
        }
        printf("%c", int_str[i]);
    }
    printf(".%02d", fractional);
}

