import java.util.regex.Pattern;

public class Main {
    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://127.0.0.1:18923/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            if (conn.getResponseCode() == 200) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder json = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    json.append(line);
                }
                reader.close();

                List<Product> products = new ArrayList<>();
                // Regex to find individual objects in the JSON array
                Pattern objPattern = Pattern.compile("\\{[^\\}]+\\}");
                Matcher objMatcher = objPattern.matcher(json.toString());

                while (objMatcher.find()) {
                    String obj = objMatcher.group();
                    // Regex to extract name and price from the object string
                    Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]+)\"");
                    Matcher nameMatcher = namePattern.matcher(obj);
                    Pattern pricePattern = Pattern.compile("\"price\"\\s*:\\s*([0-9]*\\.?[0-9]+)");
                    Matcher priceMatcher = pricePattern.matcher(obj);

                    if (nameMatcher.find() && priceMatcher.find()) {
                        products.add(new Product(nameMatcher.group(1), Double.parseDouble(priceMatcher.group(1))));
                    }
                }

                // Filter products where price > 50.00
                List<Product> filtered = new ArrayList<>();
                for (Product p : products) {
                    if (p.price > 50.00) {
                        filtered.add(p);
                    }
                }

                // Sort products by name ascending
                filtered.sort(Comparator.comparing(p -> p.name));

                // Print the output in the exact specified format
                System.out.println("=== Filtered Products (price > $50.00) ===");
                System.out.println();

                double total = 0;
                for (Product p : filtered) {
                    System.out.println(p.name + ": $" + String.format("%.2f", p.price));
                    total += p.price;
                }

                System.out.println();
                System.out.println("Count: " + filtered.size());
                System.out.println("Total: $" + String.format("%.2f", total));
            }
        } catch (Exception e) {
            // Silent catch to ensure no extra output is printed on error
        }
    }
}

