struct Edge: Codable {
    let from: String
    let to: String
    let weight: Double
}

struct GraphData: Codable {
    let nodes: [String]
    let edges: [Edge]
}

let filePath = "/tmp/…/graph.json"

func solve() {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)) else {
        return
    }

    let graphData: GraphData
    do {
        graphData = try JSONDecoder().decode(GraphData.self, from: data)
    } catch {
        return
    }

    var adj = [String: [(node: String, weight: Double)]]()
    for node in graphData.nodes {
        adj[node] = []
    }

    for edge in graphData.edges {
        adj[edge.from]?.append((node: edge.to, weight: edge.weight))
        adj[edge.to]?.append((node: edge.from, weight: edge.weight))
    }

    var distances = [String: Double]()
    for node in graphData.nodes {
        distances[node] = Double.infinity
    }

    // Ensure "A" is initialized even if not in the nodes list, 
    // though the prompt implies it is a node in the graph.
    distances["A"] = 0.0

    var pq = [(node: String, dist: Double)]()
    pq.append(("A", 0.0))

    while !pq.isEmpty {
        // Simple priority queue simulation using sort
        pq.sort { $0.dist < $1.dist }
        let current = pq.removeFirst()
        let u = current.node
        let d = current.dist

        if d > (distances[u] ?? Double.infinity) {
            continue
        }

        for neighbor in adj[u] ?? [] {
            let newDist = d + neighbor.weight
            if newDist < (distances[neighbor.node] ?? Double.infinity) {
                distances[neighbor.node] = newDist
                pq.append((neighbor.node, newDist))
            }
        }
    }

    print("=== Shortest Paths from A ===")
    print("")
    let sortedNodes = graphData.nodes.sorted()
    for node in sortedNodes {
        let dist = distances[node] ?? Double.infinity
        let distStr = dist == Double.infinity ? "Infinity" : String(format: "%g", dist)
        print("A -> \(node): \(distStr)")
    }
}

