import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

class MinHeap {
    private heap: { node: string; dist: number }[] = [];

    push(val: { node: string; dist: number }) {
        this.heap.push(val);
        this.bubbleUp(this.heap.length - 1);
    }

    pop(): { node: string; dist: number } | undefined {
        if (this.heap.length === 0) return undefined;
        if (this.heap.length === 1) return this.heap.pop();
        const top = this.heap[0];
        this.heap[0] = this.heap.pop()!;
        this.bubbleDown(0);
        return top;
    }

    private bubbleUp(index: number) {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (this.heap[parentIndex].dist <= this.heap[index].dist) break;
            [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];
            index = parentIndex;
        }
    }

    private bubbleDown(index: number) {
        while (true) {
            let smallest = index;
            const left = 2 * index + 1;
            const right = 2 * index + 2;
            if (left < this.heap.length && this.heap[left].dist < this.heap[smallest].dist) {
                smallest = left;
            }
            if (right < this.heap.length && this.heap[right].dist < this.heap[smallest].dist) {
                smallest = right;
            }
            if (smallest === index) break;
            [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
            index = smallest;
        }
    }

    isEmpty() {
        return this.heap.length === 0;
    }
}

function main() {
    const filePath = '/tmp/…/graph.json';

    try {
        const rawData = fs.readFileSync(filePath, 'utf8');
        const data: GraphData = JSON.parse(rawData);

        const adj = new Map<string, Array<{ node: string; weight: number }>>();
        data.nodes.forEach(node => adj.set(node, []));

        data.edges.forEach(edge => {
            const from = edge.from;
            const to = edge.to;
            const weight = edge.weight;
            if (adj.has(from) && adj.has(to)) {
                adj.get(from)!.push({ node: to, weight });
                adj.get(to)!.push({ node: from, weight });
            }
        });

        const distances = new Map<string, number>();
        data.nodes.forEach(node => distances.set(node, Infinity));

        if (data.nodes.includes("A")) {
            distances.set("A", 0);
            const pq = new MinHeap();
            pq.push({ node: "A", dist: 0 });

            while (!pq.isEmpty()) {
                const item = pq.pop();
                if (!item) break;
                const { node: u, dist: d } = item;

                if (d > (distances.get(u) ?? Infinity)) continue;

                const neighbors = adj.get(u) || [];
                for (const { node: v, weight } of neighbors) {
                    const newDist = d + weight;
                    if (newDist < (distances.get(v) ?? Infinity)) {
                        distances.set(v, newDist);
                        pq.push({ node: v, dist: newDist });
                    }
                }
            }

            console.log("=== Shortest Paths from A ===");
            console.log("");
            const sortedNodes = [...data.nodes].sort();
            for (const node of sortedNodes) {
                const dist = distances.get(node);
                console.log(`A -> ${node}: ${dist === Infinity ? "Infinity" : dist}`);
            }
        }
    } catch (err) {
        // Silent fail
    }
}

