import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.util.regex.*;

public class Main {
    static class Edge {
        String to;
        long weight;
        Edge(String to, long weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class Node implements Comparable<Node> {
        String name;
        long dist;
        Node(String name, long dist) {
            this.name = name;
            this.dist = dist;
        }
        public int compareTo(Node other) {
            return Long.compare(this.dist, other.dist);
        }
    }

    public static void main(String[] args) {
        try {
            String path = "/tmp/…/graph.json";
            byte[] encoded = Files.readAllBytes(Paths.get(path));
            String content = new String(encoded);

            List<String> nodeNames = new ArrayList<>();
            Pattern nodePattern = Pattern.compile("\"nodes\"\\s*:\\s*\\[([^\\]]*)\\]");
            Matcher nodeMatcher = nodePattern.matcher(content);
            if (nodeMatcher.find()) {
                String nodesStr = nodeMatcher.group(1);
                String[] parts = nodesStr.split(",");
                for (String p : parts) {
                    String name = p.trim().replace("\"", "");
                    if (!name.isEmpty()) {
                        nodeNames.add(name);
                    }
                }
            }

            Map<String, List<Edge>> adj = new HashMap<>();
            for (String name : nodeNames) {
                adj.put(name, new ArrayList<>());
            }

            Pattern edgePattern = Pattern.compile("\"from\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"to\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"weight\"\\s*:\\s*(\\d+)");
            Matcher edgeMatcher = edgePattern.matcher(content);
            while (edgeMatcher.find()) {
                String u = edgeMatcher.group(1);
                String v = edgeMatcher.group(2);
                long w = Long.parseLong(edgeMatcher.group(3));
                if (adj.containsKey(u) && adj.containsKey(v)) {
                    adj.get(u).add(new Edge(v, w));
                    adj.get(v).add(new Edge(u, w));
                }
            }

            Map<String, Long> distances = new HashMap<>();
            for (String name : nodeNames) {
                distances.put(name, Long.MAX_VALUE);
            }

            if (distances.containsKey("A")) {
                distances.put("A", 0L);
                PriorityQueue<Node> pq = new PriorityQueue<>();
                pq.add(new Node("A", 0L));

                while (!pq.isEmpty()) {
                    Node curr = pq.poll();
                    if (curr.dist > distances.get(curr.name)) continue;

                    List<Edge> edges = adj.get(curr.name);
                    if (edges != null) {
                        for (Edge e : edges) {
                            long newDist = distances.get(curr.name) + e.weight;
                            if (newDist < distances.get(e.to)) {
                                distances.put(e.to, newDist);
                                pq.add(new Node(e.to, newDist));
                            }
                        }
                    }
                }
            }

            System.out.println("=== Shortest Paths from A ===");
