    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };

    let reader = BufReader::new(file);

    let mut levels = BTreeMap::new();
    let mut error_counts = HashMap::new();
    let mut unique_errors = BTreeSet::new();
    let mut hour_counts = HashMap::new();

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => continue,
        };

        if line.is_empty() {
            continue;
        }

        // Expected format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        if let Some(end_bracket) = line.find(']') {
            let timestamp = &line[1..end_bracket];
            // Timestamp is "YYYY-MM-DD HH:MM:SS", HH is at indices 11 and 12
            let hour = &timestamp[11..13];

            let rest = &line[end_bracket + 2..];
            if let Some(paren_start) = rest.find('(') {
                let level = rest[..paren_start].trim();

                if let Some(paren_end) = rest.find(')') {
                    let component = &rest[paren_start + 1..paren_end];

                    if let Some(dash_idx) = rest.find(" - ") {
                        let message = &rest[dash_idx + 3..];

                        *levels.entry(level.to_string()).or_insert(0) += 1;

                        if level == "ERROR" {
                            *error_counts.entry(component.to_string()).or_insert(0) += 1;
                            unique_errors.insert(message.to_string());
                        }

                        *hour_counts.entry(format!("{}:00", hour)).or_insert(0) += 1;
                    }
                }
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();

