    println!();

    let mut max_errors = 0;
    let mut most_error_component = "None";
    for (comp, count) in &error_counts {
        if *count > max_errors {
            max_errors = *count;
            most_error_component = comp;
        }
    }
    println!("Component with Most Errors: {} ({} errors)", most_error_component, max_errors);
