import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        long lines;
        long chars;

        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) {
        Path rootPath = Paths.get("/tmp/…/project_tree");
        TreeMap<String, List<FileInfo>> extensionMap = new TreeMap<>();

        try {
            Files.walkFileTree(rootPath, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    if (attrs.isRegularFile()) {
                        Path relative = rootPath.relativize(file);
                        String relStr = relative.toString().replace("\\", "/");

                        String fileName = file.getFileName().toString();
                        int dotIndex = fileName.lastIndexOf('.');
                        String ext = (dotIndex == -1) ? "" : fileName.substring(dotIndex);

                        long lines = countLines(file);
                        long chars = 0;
                        try {
                            chars = Files.size(file);
                        } catch (IOException e) {
                            chars = 0;
                        }

                        extensionMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relStr, lines, chars));
                    }
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult visitFileFailed(Path file, IOException exc) {
                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            // Root path might not exist or be inaccessible
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileInfo>> entry : extensionMap.entrySet()) {
            List<FileInfo> files = entry.getValue();
            Collections.sort(files, Comparator.comparing(f -> f.relPath));

            String ext = entry.getKey();
            long extFiles = files.size();
            long extLines = 0;
            long extChars = 0;

            for (FileInfo f : files) {
                extLines += f.lines;
                extChars += f.chars;
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + extFiles);
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);
            for (FileInfo f : files) {
                System.out.println("    " + f.relPath + ": " + f.lines + " lines, " + f.chars + " chars");
            }

            totalFiles += extFiles;
            totalLines += extLines;
            totalChars += extChars;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    private static long countLines(Path path) {
        long count = 0;
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            while (reader.readLine() != null) {
                count++;
            }
        } catch (Exception e) {
            // Handle binary files or other reading errors by returning 0 lines
        }
        return count;
    }
}

