use std::collections::{BinaryHeap, HashMap};
use std::fs;

#[derive(Debug, Clone)]
struct State {
    cost: f64,
    node: String,
}

impl PartialEq for State {
    fn eq(&self, other: &Self) -> bool {
        self.cost == other.cost && self.node == other.node
    }
}

impl Eq for State {}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        other.cost.partial_cmp(&self.cost)
    }
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.partial_cmp(other).unwrap()
    }
}

fn extract_value(block: &str, key: &str) -> String {
    if let Some(key_pos) = block.find(key) {
        let after_key = &block[key_pos + key.len()..];
        if let Some(colon_pos) = after_key.find(':') {
            let after_colon = &after_key[colon_pos + 1..];
            let trimmed = after_colon.trim();
            if trimmed.starts_with('"') {
                let end_quote = trimmed[1..].find('"').unwrap_or(trimmed.len());
                return trimmed[1..1 + end_quote].to_string();
            } else {
                let end_char = trimmed.find(|c| c == ',' || c == '}').unwrap_or(trimmed.len());
                return trimmed[..end_char].trim().to_string();
            }
        }
    }
    "".to_string()
}

fn parse_json(content: &str) -> (Vec<String>, Vec<(String, String, f64)>) {
    let mut nodes = Vec::new();
    let mut edges = Vec::new();

    if let Some(start) = content.find("\"nodes\"") {
        let mut search_idx = start;
        while search_idx < content.len() {
            if content[search_idx..].starts_with("[") {
                let end = content[search_idx..].find(']').unwrap();
                let node_str = &content[search_idx + 1..search_idx + end];
                for s in node_str.split(',') {
                    let trimmed = s.trim().trim_matches('"');
                    if !trimmed.is_empty() {
                        nodes.push(trimmed.to_string());
                    }
                }
                break;
            }
            search_idx += 1;
        }
    }

    if let Some(start) = content.find("\"edges\"") {
        let mut search_idx = start;
        while search_idx < content.len() {
            if content[search_idx..].starts_with("[") {
                let end = content[search_idx..].find(']').unwrap();
                let edge_str = &content[search_idx + 1..search_idx + end];
                let mut current_pos = 0;
                while let Some(block_start) = edge_str[current_pos..].find('{') {
                    let block_start = current_pos + block_start;
                    if let Some(block_end) = edge_str[block_start..].find('}') {
                        let block_end = block_start + block_end;
                        let block = &edge_str[block_start..block_end];
                        let from = extract_value(block, "\"from\"");
                        let to = extract_value(block, "\"to\"");
                        let weight_str = extract_value(block, "\"weight\"");
                        if let Ok(weight) = weight_str.parse::<f64>() {
                            edges.push((from, to, weight));
                        }
                        current_pos = block_end + 1;
                    } else {
                        break;
                    }
                }
                break;
            }
            search_idx += 1;
        }
    }
    (nodes, edges)
}

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("Could not read file");
    let (nodes, edges) = parse_json(&content);

    let mut adj = HashMap::new();
    for node in &nodes {
        adj.insert(node.clone(), Vec::new());
    }
    for (u, v, w) in edges {
        if let Some(list) = adj.get_mut(&u) {
            list.push((v.clone(), w));
        }
        if let Some(list) = adj.get_mut(&v) {
            list.push((u.clone(), w));
        }
    }

    let mut dists = HashMap::new();
    for node in &nodes {
        dists.insert(node.clone(), f64::INFINITY);
    }

    if let Some(start_node) = nodes.iter().find(|&n| n == "A") {
        dists.insert(start_node.clone(), 0.0);
        let mut pq = BinaryHeap::new();
        pq.push(State { cost: 0.0, node: start_node.clone() });

        while let Some(State { cost, node }) = pq.pop() {
            if cost > *dists.get(&node).unwrap() {
                continue;
            }
            if let Some(neighbors) = adj.get(&node) {
                for (next_node, weight) in neighbors {
                    let next_dist = cost + weight;
                    if next_dist < *dists.get(next_node).unwrap() {
                        dists.insert(next_node.clone(), next_dist);
                        pq.push(State { cost: next_dist, node: next_node.clone() });
                    }
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes = nodes.clone();
    sorted_nodes.sort();
    for node in sorted_nodes {
        let d = dists.get(&node).unwrap();
        println!("A -> {}: {}", node, d);
    }
}

