use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn main() {
    // 1. Make HTTP GET request
    let response_body = fetch_products("127.0.0.1:18923");

    // 2. Parse the JSON response
    let products = parse_products_json(&response_body);

    // 3. Filter to only products where price > 50.00
    let mut filtered_products: Vec<Product> = products
        .into_iter()
        .filter(|p| p.price > 50.00)
        .collect();

    // 4. Sort filtered products by name ascending (alphabetical)
    filtered_products.sort_by(|a, b| a.name.cmp(&b.name));

    // 5. Print the output in the exact format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total_price = 0.0;
    for product in &filtered_products {
        println!("{}: ${:.2}", product.name, product.price);
        total_price += product.price;
    }

    println!();
    println!("Count: {}", filtered_products.len());
    println!("Total: ${:.2}", total_price);
}

fn fetch_products(addr: &str) -> String {
    let mut stream = TcpStream::connect(addr).expect("Could not connect to server");
    let request = format!(
        "GET /api/products HTTP/1.1\r\n\
         Host: {}\r\n\
         Connection: close\r\n\r\n",
        addr
    );
    stream.write_all(request.as_bytes()).expect("Failed to send request");

    let mut response = String::new();
    stream.read_to_string(&mut response).expect("Failed to read response");

    // Separate headers from body
    if let Some(body_start) = response.find("\r\n\r\n") {
        response[body_start + 4..].to_string()
    } else {
        String::new()
    }
}

fn parse_products_json(json: &str) -> Vec<Product> {
    let mut products = Vec::new();
    let mut i = 0;
    // Manual JSON parsing for an array of objects: [{"id":...,"name":"...", "price":...}, ...]
    while let Some(start_bracket) = json[i..].find('{') {
        let start_idx = i + start_bracket;
        let end_idx = json[start_idx..].find('}').unwrap_or(0);
        if end_idx == 0 {
            break;
        }
        let end_idx = start_idx + end_idx;
        let obj_str = &json[start_idx..end_idx];

        let mut name = String::new();
        let mut price = 0.0;

        // Extract "name":"..."
        if let Some(n_pos) = obj_str.find("\"name\":\"") {
            let s = n_pos + 8;
            if let Some(e) = obj_str[s..].find('"') {
                name = obj_str[s..s + e].to_string();
            }
        }

        // Extract "price":...
        if let Some(p_pos) = obj_str.find("\"price\":") {
            let s = p_pos + 8;
            let e = obj_str[s..].find(|c: char| c == ',' || c == '}' || c == ' ').unwrap_or(0);
            let price_str = obj_str[s..s + e].trim();
            if let Ok(p) = price_str.parse::<f64>() {
                price = p;
            }
        }

        if !name.is_empty() {
            products.push(Product { name, price });
        }
        i = end_idx + 1;
    }
    products
}

