fn parse_products_json(json: &str) -> Vec<Product> {
    let mut products = Vec::new();
    let mut i = 0;
    // Manual JSON parsing for an array of objects: [{"id":...,"name":"...", "price":...}, ...]
    while let Some(start_bracket) = json[i..].find('{') {
        let start_idx = i + start_bracket;
        let end_idx = json[start_idx..].find('}').unwrap_or(0);
        if end_idx == 0 {
            break;
        }
        let end_idx = start_idx + end_idx;
        let obj_str = &json[start_idx..end_idx];

        let mut name = String::new();
        let mut price = 0.0;

        // Extract "name"
        if let Some(n_pos) = obj_str.find("\"name\"") {
            let key_end = n_pos + 6;
            if let Some(colon_pos) = obj_str[key_end..].find(':') {
                let colon_idx = key_end + colon_pos;
                let val_start = colon_idx + 1;
                if let Some(quote_pos) = obj_str[val_start..].find('"') {
                    let q_start = val_start + quote_pos + 1;
                    if let Some(q_end) = obj_str[q_start..].find('"') {
                        name = obj_str[q_start..q_start + q_end].to_string();
                    }
                }
            }
        }

        // Extract "price"
        if let Some(p_pos) = obj_str.find("\"price\"") {
            let key_end = p_pos + 7;
            if let Some(colon_pos) = obj_str[key_end..].find(':') {
                let colon_idx = key_end + colon_pos;
                let val_start = colon_idx + 1;
                let val_part = &obj_str[val_start..];
                // Price ends at a comma, closing brace, or end of string
                let end_of_val = val_part.find(|c: char| c == ',' || c == '}').unwrap_or(val_part.len());
                let price_str = val_part[..end_of_val].trim();
                if let Ok(p) = price_str.parse::<f64>() {
                    price = p;
                }
            }
        }

        if !name.is_empty() {
            products.push(Product { name, price });
        }
        i = end_idx + 1;
    }
    products
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try {
            String pathA = "/tmp/…/config_a.json";
            String pathB = "/tmp/…/config_b.json";

            String contentA = new String(Files.readAllBytes(Paths.get(pathA)));
            String contentB = new String(Files.readAllBytes(Paths.get(pathB)));

            Parser parserA = new Parser(contentA);
            Parser parserB = new Parser(contentB);

            JsonNode nodeA = parserA.parse();
            JsonNode nodeB = parserB.parse();

            JsonNode merged = merge(nodeA, nodeB);

            StringBuilder sb = new StringBuilder();
            merged.serialize(sb, 0);
            System.out.print(sb.toString());
        } catch (Exception e) {
            // Silent failure as per requirements to only output merged JSON
        }
    }

    static JsonNode merge(JsonNode a, JsonNode b) {
        if (a instanceof JsonObject && b instanceof JsonObject) {
            JsonObject objA = (JsonObject) a;
            JsonObject objB = (JsonObject) b;
            JsonObject result = new JsonObject();
            for (Map.Entry<String, JsonNode> entry : objA.map.entrySet()) {
                result.map.put(entry.getKey(), entry.getValue());
            }
            for (Map.Entry<String, JsonNode> entry : objB.map.entrySet()) {
                String key = entry.getKey();
                if (result.map.containsKey(key)) {
                    result.map.put(key, merge(result.map.get(key), entry.getValue()));
                } else {
                    result.map.put(key, entry.getValue());
                }
            }
            return result;
        } else if (a instanceof JsonArray && b instanceof JsonArray) {
            JsonArray arrA = (JsonArray) a;
            JsonArray arrB = (JsonArray) b;
            JsonArray result = new JsonArray();
            for (JsonNode node : arrA.nodes) {
                if (!contains(result, node)) result.nodes.add(node);
            }
            for (JsonNode node : arrB.nodes) {
                if (!contains(result, node)) result.nodes.add(node);
            }
            return result;
        } else {
            return b;
        }
    }

    private static boolean contains(JsonArray arr, JsonNode node) {
        for (JsonNode n : arr.nodes) {
            if (n.equals(node)) return true;
        }
        return false;
    }

    abstract static class JsonNode {
        abstract void serialize(StringBuilder sb, int indent);
        abstract boolean equals(Object o);
    }

    static class JsonObject extends JsonNode {
        TreeMap<String, JsonNode> map = new TreeMap<>();
        @Override
        void serialize(StringBuilder sb, int indent) {
            sb.append("{\n");
            int count = 0;
            for (Map.Entry<String, JsonNode> entry : map.entrySet()) {
                sb.append(repeat("  ", indent)).append("\"").append(entry.getKey()).append("\": ");
                entry.getValue().serialize(sb, indent + 2);
                count++;
                if (count < map.size()) sb.append(",");
                sb.append("\n");
            }
            sb.append(repeat("  ", indent)).append("}");
        }
        @Override
        boolean equals(Object o) {
            if (!(o instanceof JsonObject)) return false;
            JsonObject other = (JsonObject) o;
            if (map.size() != other.map.size()) return false;
            for (Map.Entry<String, JsonNode> entry : map.entrySet()) {
                JsonNode otherVal = other.map.get(entry.getKey());
                if (otherVal == null || !entry.getValue().equals(otherVal)) return false;
            }
            return true;
        }
    }

    static class JsonArray extends JsonNode {
        List<JsonNode> nodes = new ArrayList<>();
        @Override
        void serialize(StringBuilder sb, int indent) {
            sb.append("[\n");
            for (int i = 0; i < nodes.size(); i++) {
                sb.append(repeat("  ", indent)).append(nodes.get(i).serialize(sb, indent + 2));
                if (i < nodes.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(repeat("  ", indent)).append("]");
        }
        @Override
        boolean equals(Object o) {
            if (!(o instanceof JsonArray)) return false;
            JsonArray other = (JsonArray) o;
            if (nodes.size() != other.nodes.size()) return false;
            for (int i = 0; i < nodes.size(); i++) {
                if (!nodes.get(i).equals(other.nodes.get(i))) return false;
            }
            return true;
        }
    }

    static class JsonString extends JsonNode {
        String value;
        JsonString(String value) { this.value = value; }
        @Override
        void serialize(StringBuilder sb, int indent) {
            sb.append("\"").append(value).append("\"");
        }
        @Override
        boolean equals(Object o) {
            return (o instanceof JsonString && ((JsonString) o).value.equals(value));
        }
    }

    static class JsonNumber extends JsonNode {
        double value;
        JsonNumber(double value) { this.value = value; }
        @Override
        void serialize(StringBuilder sb, int indent) {
            if (value == (long) value && value <= Long.MAX_VALUE && value >= Long.MIN_VALUE) {
                sb.append((long) value);
            } else {
                sb.append(value);
            }
        }
        @Override
        boolean equals(Object o) {
            return (o instanceof JsonNumber && Double.compare(((JsonNumber) o).value, this.value) == 0);
        }
    }

    static class JsonBoolean extends JsonNode {
        boolean value;
        JsonBoolean(boolean value) { this.value = value; }
        @Override
        void serialize(StringBuilder sb, int indent) {
            sb.append(value);
        }
        @Override
        boolean equals(Object o) {
            return (o instanceof JsonBoolean && ((JsonBoolean) o).value == value);
        }
    }

    static class JsonNull extends JsonNode {
        @Override
        void serialize(StringBuilder sb, int indent) {
            sb.append("null");
        }
        @Override
        boolean equals(Object o) {
            return (o instanceof JsonNull);
        }
    }

    private static String repeat(String str, int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) sb.append(str);
        return sb.toString();
    }

    static class Parser {
        private String input;
        private int pos = 0;

        Parser(String input) { this.input = input; }

        private void skipWhitespace() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }

        JsonNode parse() {
            skipWhitespace();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
