/**
 * Executes a system command and captures its output into a dynamically allocated string.
 * Trailing newlines and whitespace are stripped.
 */
char* get_command_output(const char* cmd) {
    FILE* fp = popen(cmd, "r");
    if (fp == NULL) {
        char* error_val = malloc(8);
        if (error_val) {
            strcpy(error_val, "unknown");
        }
        return error_val;
    }

    // Allocate a sufficiently large buffer for command output
    char* buffer = (char*)malloc(4096);
    if (buffer == NULL) {
        pclose(fp);
        return NULL;
    }

    if (fgets(buffer, 4096, fp) == NULL) {
        buffer[0] = '\0';
    }
    pclose(fp);

    // Strip trailing newlines and whitespace
    size_t len = strlen(buffer);
    while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r' || buffer[len - 1] == ' ')) {
        buffer[len - 1] = '\0';
        len--;
    }

    return buffer;
}

int main(void) {
    // Capture outputs for each required command
    char* hostname = get_command_output("hostname");
    char* os = get_command_output("uname -s");
    char* architecture = get_command_output("uname -m");
    char* username = get_command_output("whoami");

    // Ensure pointers are not NULL before printing
    char* h_out = hostname ? hostname : "unknown";
    char* o_out = os ? os : "unknown";
    char* a_out = architecture ? architecture : "unknown";
