}

import * as fs from 'fs';
import * as path from 'path';

const projectTree = '/tmp/…/project_tree';

interface FileData {
  relativePath: string;
  lines: number;
  chars: number;
}

const extensionMap = new Map<string, FileData[]>();

function walk(dir: string) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isSymbolicLink()) {
        continue;
      }

      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.isFile()) {
        const ext = path.extname(fullPath);
        const buffer = fs.readFileSync(fullPath);

        let lines = 0;
        for (let i = 0; i < buffer.length; i++) {
          if (buffer[i] === 10) { // \n character
            lines++;
          }
        }

        const chars = buffer.length;
        const relativePath = path.relative(projectTree, fullPath).replace(/\\/g, '/');

        if (!extensionMap.has(ext)) {
          extensionMap.set(ext, []);
        }
        extensionMap.get(ext)!.push({
          relativePath,
          lines,
          chars
        });
      }
    }
  } catch (e) {
    // Skip directories that cannot be accessed
  }
}

walk(projectTree);

const sortedExtensions = Array.from(extensionMap.keys()).sort();

process.stdout.write("=== File Tree Analysis ===\n\n");

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExtensions) {
  const files = extensionMap.get(ext)!;
  files.sort((a, b) => a.relativePath.localeCompare(b.relativePath));

  let extFiles = 0;
  let extLines = 0;
  let extChars = 0;

  for (const f of files) {
    extFiles += 1;
    extLines += f.lines;
    extChars += f.chars;
  }

  process.stdout.write(`Extension: ${ext}\n`);
  process.stdout.write(`  Files: ${files.length}\n`);
  process.stdout.write(`  Total Lines: ${extLines}\n`);
  process.stdout.write(`  Total Characters: ${extChars}\n`);

  for (const f of files) {
    process.stdout.write(`    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`);
  }

  totalFiles += extFiles;
  totalLines += extLines;
  totalChars += extChars;
}

process.stdout.write(`\nTotal: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`);

