#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} JSONType;

struct JSONValue;

typedef struct {
    char* key;
    struct JSONValue* value;
} KeyValuePair;

typedef struct JSONValue {
    JSONType type;
    union {
        bool boolean;
        double number;
        char* string;
        struct {
            struct JSONValue** elements;
            size_t count;
        } array;
        struct {
            KeyValuePair* pairs;
            size_t count;
        } object;
    } data;
} JSONValue;

JSONValue* create_null() {
    JSONValue* val = malloc(sizeof(JSONValue));
    val->type = JSON_NULL;
    return val;
}

JSONValue* create_bool(bool b) {
    JSONValue* val = malloc(sizeof(JSONValue));
    val->type = JSON_BOOL;
    val->data.boolean = b;
    return val;
}

JSONValue* create_number(double n) {
    JSONValue* val = malloc(sizeof(JSONValue));
    val->type = JSON_NUMBER;
    val->data.number = n;
    return val;
}

JSONValue* create_string(const char* s) {
    JSONValue* val = malloc(sizeof(JSONValue));
    val->type = JSON_STRING;
    val->data.string = strdup(s);
    return val;
}

JSONValue* create_array() {
    JSONValue* val = malloc(sizeof(JSONValue));
    val->type = JSON_ARRAY;
    val->data.array.elements = NULL;
    val->data.array.count = 0;
    return val;
}

JSONValue* create_object() {
    JSONValue* val = malloc(sizeof(JSONValue));
    val->type = JSON_OBJECT;
    val->data.object.pairs = NULL;
    val->data.object.count = 0;
    return val;
}

void free_json(JSONValue* val) {
    if (!val) return;
    if (val->type == JSON_STRING) {
        free(val->data.string);
    } else if (val->type == JSON_ARRAY) {
        for (size_t i = 0; i < val->data.array.count; i++) {
            free_json(val->data.array.elements[i]);
        }
        free(val->data.array.elements);
    } else if (val->type == JSON_OBJECT) {
        for (size_t i = 0; i < val->data.object.count; i++) {
            free(val->data.object.pairs[i].key);
            free_json(val->data.object.pairs[i].value);
        }
        free(val->data.object.pairs);
    }
    free(val);
}

JSONValue* deep_copy(JSONValue* val) {
    if (!val) return NULL;
    JSONValue* new_val = malloc(sizeof(JSONValue));
    new_val->type = val->type;
    switch (val->type) {
        case JSON_NULL: break;
        case JSON_BOOL: new_val->data.boolean = val->data.boolean; break;
        case JSON_NUMBER: new_val->data.number = val->data.number; break;
        case JSON_STRING: new_val->data.string = strdup(val->data.string); break;
        case JSON_ARRAY:
            new_val->data.array.count = val->data.array.count;
            new_val->data.array.elements = malloc(sizeof(JSONValue*) * val->data.array.count);
            for (size_t i = 0; i < val->data.array.count; i++) {
                new_val->data.array.elements[i] = deep_copy(val->data.array.elements[i]);
            }
            break;
        case JSON_OBJECT:
            new_val->data.object.count = val->data.object.count;
            new_val->data.object.pairs = malloc(sizeof(KeyValuePair) * val->data.object.count);
            for (size_t i = 0; i < val->data.object.count; i++) {
                new_val->data.object.pairs[i].key = strdup(val->data.object.pairs[i].key);
                new_val->data.object.pairs[i].value = deep_copy(val->data.object.pairs[i].value);
            }
            break;
    }
    return new_val;
}

bool is_equal(JSONValue* a, JSONValue* b);

bool is_in_array(JSONValue* arr, JSONValue* val) {
    for (size_t i = 0; i < arr->data.array.count; i++) {
        if (is_equal(arr->data.array.elements[i], val)) return true;
    }
    return false;
}

bool is_equal(JSONValue* a, JSONValue* b) {
    if (a->type != b->type) return false;
    switch (a->type) {
        case JSON_NULL: return true;
        case JSON_BOOL: return a->data.boolean == b->data.boolean;
        case JSON_NUMBER: return a->data.number == b->data.number;
        case JSON_STRING: return strcmp(a->data.string, b->data.string) == 0;
        case JSON_ARRAY:
            if (a->data.array.count != b->data.array.count) return false;
            for (size_t i = 0; i < a->data.array.count; i++) {
                if (!is_equal(a->data.array.elements[i], b->data.array.elements[i])) return false;
            }
            return true;
        case JSON_OBJECT:
            if (a->data.object.count != b->data.object.count) return false;
            for (size_t i = 0; i < a->data.object.count; i++) {
                if (strcmp(a->data.object.pairs[i].key, b->data.object.pairs[i].key) != 0 ||
                    !is_equal(a->data.object.pairs[i].value, b->data.object.pairs[i].value)) return false;
            }
            return true;
    }
    return false;
}

void add_pair_to_object(JSONValue* obj, const char* key, JSONValue* value) {
    obj->data.object.pairs = realloc(obj->data.object.pairs, (obj->data.object.count + 1) * sizeof(KeyValuePair));
    obj->data.object.pairs[obj->data.object.count].key = strdup(key);
    obj->data.object.pairs[obj->data.object.count].value = value;
    obj->data.object.count++;
