typedef struct {
    int node_idx;
    double dist;
} PQItem;

typedef struct {
    PQItem *items;
    int size;
    int capacity;
} PriorityQueue;

PriorityQueue* create_pq(int capacity) {
    PriorityQueue *pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->items = (PQItem*)malloc(sizeof(PQItem) * capacity);
    pq->size = 0;
    pq->capacity = capacity;
    return pq;
}

void push(PriorityQueue *pq, int node_idx, double dist) {
    if (pq->size == pq->capacity) {
        pq->capacity *= 2;
        pq->items = (PQItem*)realloc(pq->items, sizeof(PQItem) * pq->capacity);
    }
    int i = pq->size++;
    pq->items[i].node_idx = node_idx;
    pq->items[i].dist = dist;
    while (i > 0 && pq->items[i].dist < pq->items[(i - 1) / 2].dist) {
        PQItem temp = pq->items[i];
        pq->items[i] = pq->items[(i - 1) / 2];
        pq->items[(i - 1) / 2] = temp;
        i = (i - 1) / 2;
    }
}

PQItem pop(PriorityQueue *pq) {
    PQItem root = pq->items[0];
    pq->items[0] = pq->items[--pq->size];
    int i = 0;
    while (i * 2 + 1 < pq->size) {
        int child = i * 2 + 1;
        if (child + 1 < pq->size && pq->items[child + 1].dist < pq->items[child].dist) {
            child++;
        }
        if (pq->items[i].dist <= pq->items[child].dist) break;
        PQItem temp = pq->items[i];
        pq->items[i] = pq->items[child];
        pq->items[child] = temp;
        i = child;
    }
    return root;
}

