use std::collections::BTreeMap;
use std::fs;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};

struct FileStats {
    lines: usize,
    chars: usize,
}

fn process_dir(current_path: &Path, root_path: &Path, stats_map: &mut BTreeMap<String, BTreeMap<String, FileStats>>) {
    if let Ok(entries) = fs::read_dir(current_path) {
        for entry in entries.flatten() {
            let path = entry.path();
            let metadata = match fs::symlink_metadata(&path) {
                Ok(m) => m,
                Err(_) => continue,
            };

            if metadata.is_symlink() {
                continue;
            }

            if metadata.is_dir() {
                process_dir(&path, root_path, stats_map);
            } else if metadata.is_file() {
                let relative_path = path
                    .strip_prefix(root_path)
                    .map(|p| p.to_string_lossy().replace('\\', "/"))
                    .unwrap_or_else(|_| "unknown".to_string());

                let extension = path
                    .extension()
                    .and_then(|s| s.to_str())
                    .map(|s| format!(".{}", s))
                    .unwrap_or_default();

                if let Ok(file) = fs::File::open(&path) {
                    let mut line_count = 0;
                    let mut byte_count = 0;
                    let mut reader = BufReader::new(file);
                    let mut buf = [0u8; 8192];
                    let mut has_content = false;
                    let mut last_byte = 0u8;

                    loop {
                        match reader.read(&mut buf) {
                            Ok(0) => break,
                            Ok(n) => {
                                has_content = true;
                                byte_count += n;
                                for i in 0..n {
                                    if buf[i] == b'\n' {
                                        line_count += 1;
                                    }
                                    last_byte = buf[i];
                                }
                            }
                            Err(_) => break,
                        }
                    }

                    if has_content && last_byte != b'\n' {
                        line_count += 1;
                    }

                    stats_map
                        .entry(extension)
                        .or_insert_with(BTreeMap::new)
                        .insert(relative_path, FileStats {
                            lines: line_count,
                            chars: byte_count,
                        });
                }
            }
        }
    }
}

fn main() {
    let root_path = Path::new("/tmp/…/project_tree");
    let mut stats_map: BTreeMap<String, BTreeMap<String, FileStats>> = BTreeMap::new();

    process_dir(root_path, root_path, &mut stats_map);

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0;
    let mut total_lines = 0;
    let mut total_chars = 0;

    for (ext, files) in &stats_map {
        let mut ext_lines = 0;
        let mut ext_chars = 0;

        for stats in files.values() {
            ext_lines += stats.lines;
            ext_chars += stats.chars;
        }

        println!("Extension: {}", ext);
        println!("  Files: {}", files.len());
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);

        for (path, stats) in files {
            println!("    {}: {} lines, {} chars", path, stats.lines, stats.chars);
        }

        total_files += files.len();
        total_lines += ext_lines;
        total_chars += ext_chars;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

