// Determinant calculation using recursion
func determinant(_ matrix: [[Int]]) -> Int {
    let n = matrix.count
    if n == 1 {
        return matrix[0][0]
    }
    if n == 2 {
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    }

    var det = 0
    for j in 0..<n {
        var subMatrix = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n {
                if k != j {
                    row.append(matrix[i][k])
                }
            }
            subMatrix.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * matrix[0][j] * determinant(subMatrix)
    }
    return det
}

