use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Object(BTreeMap<String, Value>),
    Array(Vec<Value>),
    String(String),
    Number(f64),
    Boolean(bool),
    Null,
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn consume(&mut self) -> char {
        let c = self.input[self.pos..].chars().next().expect("Unexpected end of input");
        self.pos += c.len_utf8();
        c
    }

    fn consume_str(&mut self, s: &str) -> bool {
        if self.input[self.pos..].starts_with(s) {
            self.pos += s.len();
            true
        } else {
            false
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.consume();
            } else {
                break;
            }
        }
    }
}

fn parse_value(p: &mut Parser) -> Value {
    p.skip_whitespace();
    let c = p.peek();
    match c {
        Some('{') => parse_object(p),
        Some('[') => parse_array(p),
        Some('"') => parse_string(p),
        Some('t') => parse_true(p),
        Some('f') => parse_false(p),
        Some('n') => parse_null(p),
        _ => parse_number(p),
    }
}

fn parse_string(p: &mut Parser) -> Value {
    p.consume(); // "
    let mut s = String::new();
    while let Some(c) = p.peek() {
        if c == Some('"') {
            p.consume();
            break;
        }
        if c == Some('\\') {
            p.consume();
            match p.consume() {
                '"' => s.push('"'),
                '\\' => s.push('\\'),
                '/' => s.push('/'),
                'b' => s.push('\x08'),
                'f' => s.push('\x0c'),
                'n' => s.push('\n'),
                'r' => s.push('\r'),
                't' => s.push('\t'),
                _ => {}
            }
        } else {
            s.push(p.consume());
        }
    }
    Value::String(s)
}

fn parse_number(p: &mut Parser) -> Value {
    let mut s = String::new();
    while let Some(c) = p.peek() {
        if c.is_digit(10) || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+' {
            s.push(p.consume());
        } else {
            break;
        }
    }
    let n = s.parse::<f64>().unwrap_or(0.0);
    Value::Number(n)
}

fn parse_true(p: &mut Parser) -> Value {
    p.consume_str("true");
    Value::Boolean(true)
}

fn parse_false(p: &mut Parser) -> Value {
    p.consume_str("false");
    Value::Boolean(false)
}

fn parse_null(p: &mut Parser) -> Value {
    p.consume_str("null");
    Value::Null
}

fn parse_object(p: &mut Parser) -> Value {
    p.consume(); // {
    let mut map = BTreeMap::new();
    p.skip_whitespace();
    if p.peek() == Some('}') {
        p.consume();
        return Value::Object(map);
    }
    loop {
        p.skip_whitespace();
        let key_val = parse_string(p);
        if let Value::String(key) = key_val {
            p.skip_whitespace();
            p.consume(); // :
            let val = parse_value(p);
            map.insert(key, val);
        }
        p.skip_whitespace();
        match p.peek() {
            Some(',') => {
                p.consume();
                continue;
            }
            Some('}') => {
                p.consume();
                break;
            }
            _ => break,
        }
    }
    Value::Object(map)
}

fn parse_array(p: &mut Parser) -> Value {
    p.consume(); // [
    let mut arr = Vec::new();
    p.skip_whitespace();
    if p.peek() == Some(']') {
        p.consume();
        return Value::Array(arr);
    }
    loop {
        arr.push(parse_value(p));
        p.skip_whitespace();
        match p.peek() {
            Some(',') => {
                p.consume();
                continue;
            }
            Some(']') => {
                p.consume();
                break;
            }
            _ => break,
        }
    }
    Value::Array(arr)
}

fn merge(a: Value, b: Value) -> Value {
    match (a, b) {
        (Value::Object(mut map_a), Value::Object(map_b)) => {
            for (k, v_b) in map_b {
                if let Some(v_a) = map_a.remove(&k) {
                    map_a.insert(k, merge(v_a, v_b));
                } else {
                    map_a.insert(k, v_b);
                }
            }
            Value::Object(map_a)
        }
        (Value::Array(vec_a), Value::Array(vec_b)) => {
            let mut result = vec_a;
            for item in vec_b {
                if !result.contains(&item) {
                    result.push(item);
                }
            }
            Value::Array(result)
        }
        (_, b_val) => b_val,
    }
}

fn print_json(val: &Value, indent: usize) {
    let padding = "  ".repeat(indent);
    match val {
        Value::Object(map) => {
            println!("{{");
            let keys: Vec<_> = map.keys().collect();
            for (i, k) in keys.iter().enumerate() {
