import Foundation

    let baseDirPath = "/tmp/…/project_tree"
    var baseDirPathClean = baseDirPath
    if baseDirPathClean.hasSuffix("/") {
        baseDirPathClean.removeLast()
    }

    let baseURL = URL(fileURLWithPath: baseDirPathClean)

    struct FileInfo {
        let relativePath: String
        let lineCount: Int
        let charCount: Int
    }

    var extensionMap: [String: [FileInfo]] = [:]

    func walk(url: URL) {
        do {
            let contents = try FileManager.default.contentsOfDirectory(at: url,
                                                                            includingPropertiesForKeys: [.isSymbolicLinkKey, .isDirectoryKey],
                                                                            options: [.skipsHiddenFiles])
            for item in contents {
                let resourceValues = try item.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey])
                if resourceValues.isSymbolicLink == true {
                    continue
                }
                if resourceValues.isDirectory == true {
                    walk(url: item)
                } else {
                    do {
                        let data = try Data(contentsOf: item)
                        let charCount = data.count
                        var lineCount = 0
                        for byte in data {
                            if byte == 10 {
                                lineCount += 1
                            }
                        }
                        if !data.isEmpty && data.last != 10 {
                            lineCount += 1
                        }

                        let relPath = item.path.replacingOccurrences(of: baseURL.path, with: "")
                        let finalRelPath = relPath.hasPrefix("/") ? String(relPath.dropFirst()) : relPath
                        let ext = item.pathExtension.isEmpty ? "." : ".\(item.pathExtension)"

                        let info = FileInfo(relativePath: finalRelPath, lineCount: lineCount, charCount: charCount)
                        extensionMap[ext, default: []].append(info)
                    } catch {
                        continue
                    }
                }
            }
        } catch {
            // Skip errors
        }
    }

    walk(url: baseURL)

    let sortedExtensions = extensionMap.keys.sorted()
    var totalFiles = 0
    var totalLines = 0
    var totalChars = 0

    print("=== File Tree Analysis ===")
    print("")

    for ext in sortedExtensions {
        guard let files = extensionMap[ext] else { continue }
        let sortedFiles = files.sorted { $0.relativePath < $1.relativePath }

        let extLines = sortedFiles.reduce(0) { $0 + $1.lineCount }
        let extChars = sortedFiles.reduce(0) { $0 + $1.charCount }

        totalFiles += sortedFiles.count
        totalLines += extLines
        totalChars += extChars

        print("Extension: \(ext)")
        print("  Files: \(sortedFiles.count)")
        print("  Total Lines: \(extLines)")
        print("  Total Characters: \(extChars)")
        for file in sortedFiles {
            print("    \(file.relativePath): \(file.lineCount) lines, \(file.charCount) chars")
        }
    }

    print("")
    print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")
